class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(num):
            # Count beautiful numbers from 1 to num
            if num <= 0:
                return 0
            s = str(num)
            n = len(s)
            memo = {}

            def dp(pos, tight, product, sum_, started):
                if pos == n:
                    if not started:
                        return 0
                    if sum_ == 0:
                        return 0
                    if product % sum_ == 0:
                        return 1
                    return 0

                key = (pos, tight, product, sum_, started)
                if key in memo:
                    return memo[key]

                limit = int(s[pos]) if tight else 9
                result = 0

                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_started = started or (d != 0)

                    if not new_started:
                        # Still haven't placed any non-zero digit
                        result += dp(pos + 1, new_tight, 1, 0, False)
                    else:
                        if d == 0:
                            new_product = product
                            new_sum = sum_
                        else:
                            new_product = product * d
                            new_sum = sum_ + d
                        result += dp(pos + 1, new_tight, new_product, new_sum, True)

                memo[key] = result
                return result

            return dp(0, True, 1, 0, False)

        return count(r) - count(l - 1)

