    S = input().strip()
    T = input().strip()

    if S == T:
        print("Yes")
        return

    # BFS on state (i, s) where i is position, s is start of current operation (-1 if none)
    # We use a dictionary for each i to store reachable s.
    # dp[i] is a set of s values that are reachable at position i.
    dp = [set() for _ in range(N+1)]
    dp[0].add(-1)

    for i in range(N):
        if not dp[i]:
            continue
        cur = dp[i]
        nxt = dp[i+1]
        for s in cur:
            if s == -1:
                # No active operation
                if S[i] == T[i]:
                    nxt.add(-1)
                # Try to start an operation at i
                if i + X + Y <= N:
                    # Check pattern 0^Y 1^X
                    if S[i:i+Y] == '0' * Y and S[i+Y:i+X+Y] == '1' * X:
                        nxt.add(i)
                    # Check pattern 1^Y 0^X
                    elif S[i:i+Y] == '1' * Y and S[i+Y:i+X+Y] == '0' * X:
                        nxt.add(i)
            else:
                # Active operation from s
                j = i - s
                r = j
                # Determine condition
                if r < Y:
                    # First part: expected in = S[s], out = 1-S[s]
                    if S[i] == S[s] and T[i] != S[s]:
                        if r + 1 == X + Y:
                            nxt.add(-1)
                        else:
                            nxt.add(s)
                else:
                    # Second part: expected in = 1-S[s], out = 1-S[s]
                    if S[i] != S[s] and T[i] != S[s]:
                        if r + 1 == X + Y:
                            nxt.add(-1)
                        else:
                            nxt.add(s)

    if -1 in dp[N]:
        print("Yes")
    else:
