class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        s = [ord(c) - ord('a') for c in caption]
        INF = 10**9

        # dp[i][c][t]: i characters processed, last run has char c and length t (0:1, 1:2, 2:3+)
        dp = [[[INF]*3 for _ in range(26)] for _ in range(n+1)]

        # Base: i=1, run of length 1
        for c in range(26):
            dp[1][c][0] = abs(s[0] - c)

        for i in range(1, n):
            si = s[i]
            for c in range(26):
                add = abs(si - c)

                # To run length 2
                if dp[i][c][0] < INF:
                    val = dp[i][c][0] + add
                    if val < dp[i+1][c][1]:
                        dp[i+1][c][1] = val

                # To run length 3+
                best = dp[i][c][1]
                if dp[i][c][2] < best:
                    best = dp[i][c][2]
                if best < INF:
                    val = best + add
                    if val < dp[i+1][c][2]:
                        dp[i+1][c][2] = val

                # To run length 1 (new run, different char)
                # find min over d != c of dp[i][d][2]
                min_val = INF
                for d in range(26):
                    if d == c: continue
                    if dp[i][d][2] < min_val:
                        min_val = dp[i][d][2]
                if min_val < INF:
                    val = min_val + add
                    if val < dp[i+1][c][0]:
                        dp[i+1][c][0] = val

        # suffix[i][c][t]: min cost to complete s[i:] given state (c,t) at position i
        suffix = [[[INF]*3 for _ in range(26)] for _ in range(n+1)]

        # Base: at end, valid if last run has length 3+
        for c in range(26):
            suffix[n][c][2] = 0

        for i in range(n-1, -1, -1):
            si = s[i]
            for c in range(26):
                add = abs(si - c)

                # From state (i, c, 0): must continue to (i+1, c, 1)
                if suffix[i+1][c][1] < INF:
                    val = suffix[i+1][c][1] + add
                    if val < suffix[i][c][0]:
                        suffix[i][c][0] = val

                # From state (i, c, 1): must continue to (i+1, c, 2)
                if suffix[i+1][c][2] < INF:
                    val = suffix[i+1][c][2] + add
                    if val < suffix[i][c][1]:
                        suffix[i][c][1] = val

                # From state (i, c, 2): can continue or start new
                # continue
                if suffix[i+1][c][2] < INF:
                    val = suffix[i+1][c][2] + add
                    if val < suffix[i][c][2]:
                        suffix[i][c][2] = val
                # start new: update suffix[i][d][0] for d != c
                base = suffix[i][c][2]
                if base < INF:
                    for d in range(26):
                        if d == c: continue
                        add2 = abs(si - d)
                        val = base + add2
                        if val < suffix[i][d][0]:
                            suffix[i][d][0] = val

        # Find minimum cost
        K = INF
        for c in range(26):
            if dp[n][c][2] < K:
                K = dp[n][c][2]

        if K >= INF:
            return ""

        # Reconstruct
        res = []
        i = 0
        # Find initial character
        state_c = -1
        state_t = -1
        for c in range(26):
            if dp[1][c][0] + suffix[1][c][0] == K:
                state_c = c
                state_t = 0
                res.append(chr(c + ord('a')))
                i = 1
                break

        if i == 0:
            return ""

        while i < n:
            found = False
            for d in range(26):
                if state_t == 0 or state_t == 1:
                    if d != state_c:
                        continue
                    next_t = state_t + 1
                    if dp[i+1][state_c][next_t] + suffix[i+1][state_c][next_t] == K:
                        res.append(chr(state_c + ord('a')))
                        state_t = next_t
                        i += 1
                        found = True
                        break
                else:  # state_t == 2
                    if d == state_c:
                        if dp[i+1][state_c][2] + suffix[i+1][state_c][2] == K:
                            res.append(chr(state_c + ord('a')))
                            i += 1
                            found = True
                            break
                    else:
                        if dp[i+1][d][0] + suffix[i+1][d][0] == K:
                            res.append(chr(d + ord('a')))
                            state_c = d
                            state_t = 0
                            i += 1
                            found = True
                            break
            if not found:
                return ""

        return "".join(res)

