    N, X = map(int, input().split())
    items1, items2, items3 = [], [], []
    for _ in range(N):
        V, A, C = map(int, input().split())
        if V == 1:
            items1.append((C, A))
        elif V == 2:
            items2.append((C, A))
        else:
            items3.append((C, A))

    # DP for each group: max vitamin for exactly c calories, then make non-decreasing
    def compute_dp(items):
        dp = [0] * (X + 1)
        for cal, vit in items:
            for c in range(X, cal - 1, -1):
                if dp[c - cal] + vit > dp[c]:
                    dp[c] = dp[c - cal] + vit
        # make non-decreasing: dp[c] = max vitamin with at most c calories
        for c in range(1, X + 1):
            if dp[c] < dp[c-1]:
                dp[c] = dp[c-1]
        return dp

    dp1 = compute_dp(items1)
    dp2 = compute_dp(items2)
    dp3 = compute_dp(items3)

    # best23[rem] = max_{c2=0..rem} min(dp2[c2], dp3[rem-c2])
    best23 = [0] * (X + 1)
    for rem in range(X + 1):
        best = 0
        # c2 from 0 to rem
        for c2 in range(rem + 1):
            c3 = rem - c2
            val = dp2[c2] if dp2[c2] < dp3[c3] else dp3[c3]
            if val > best:
                best = val
        best23[rem] = best

    # answer = max_{c1=0..X} min(dp1[c1], best23[X-c1])
    ans = 0
    for c1 in range(X + 1):
        v1 = dp1[c1]
        v23 = best23[X - c1]
        val = v1 if v1 < v23 else v23
        if val > ans:
