MOD = 998244353
G = 3

def ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]
    length = 2
    while length <= n:
        wlen = pow(G, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        for i in range(0, n, length):
            w = 1
            half = length >> 1
            for j in range(i, i + half):
                u = a[j]
                v = a[j + half] * w % MOD
                a[j] = (u + v) % MOD
                a[j + half] = (u - v + MOD) % MOD
                w = w * wlen % MOD
        length <<= 1
    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD

def multiply(a, b):
    n = 1
    while n < len(a) + len(b) - 1:
        n <<= 1
    fa = a + [0] * (n - len(a))
    fb = b + [0] * (n - len(b))
    ntt(fa, False)
    ntt(fb, False)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    ntt(fa, True)
    return fa[:len(a) + len(b) - 1]

def solve():
    N = int(sys.stdin.readline())
    # Compute digit counts and sums
    a_d = [0] * 7
    sum_d = [0] * 7
    for i in range(1, N + 1):
        if i < 10:
            d = 1
        elif i < 100:
            d = 2
        elif i < 1000:
            d = 3
        elif i < 10000:
            d = 4
        elif i < 100000:
            d = 5
        else:
            d = 6
        a_d[d] += 1
        sum_d[d] += i

    # Precompute factorials and inverse factorials
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (N + 1)
    inv_fact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    # Compute polynomial A(x) = prod_{d=1}^6 (1 + w_d x)^{a_d}
    A = [1]
    for d in range(1, 7):
        if a_d[d] == 0:
            continue
        w = pow(10, d, MOD)
        a = a_d[d]
        P = [0] * (a + 1)
        w_pow = 1
        for k in range(a + 1):
            P[k] = fact[a] * inv_fact[k] % MOD * inv_fact[a - k] % MOD * w_pow % MOD
            w_pow = w_pow * w % MOD
        A = multiply(A, P)
        if len(A) > N + 1:
            A = A[:N + 1]

    # Compute polynomial B(x) = sum_{m=0}^{N-1} (1/C(N-1, m)) x^m
    B = [0] * N
    if N == 1:
        B[0] = 1
    else:
        inv_fact_N_1 = inv_fact[N - 1]
        for m in range(N):
            B[m] = inv_fact[m] * inv_fact[N - 1 - m] % MOD * inv_fact_N_1 % MOD

    # Compute C(x) = A(x) * B(x) and take first N coefficients
    C = multiply(A, B)
    c = C[:N]

    # Compute S_d for d=1..6
    S = [0] * 7
    for d in range(1, 7):
        w = pow(10, d, MOD)
        neg_w = (MOD - w) % MOD
        pow_neg = [1] * N
        for t in range(1, N):
            pow_neg[t] = pow_neg[t - 1] * neg_w % MOD
        s = 0
        for j in range(N):
            s = (s + c[j] * pow_neg[N - 1 - j]) % MOD
        S[d] = s

    # Compute total sum
    total = 0
    for d in range(1, 7):
        total = (total + sum_d[d] * S[d]) % MOD
    total = total * fact[N - 1] % MOD
    print(total)

