import sys

def solve():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it))
    intervals = []
    for _ in range(N):
        L = int(next(it))
        R = int(next(it))
        intervals.append((L, R))
    Q = int(next(it))
    queries = [int(next(it)) for _ in range(Q)]

    MAX = 500000

    class SegmentTree:
        __slots__ = ('n', 'size', 'minv', 'maxv', 'lazy')
        def __init__(self, n):
            self.n = n
            self.size = 1
            while self.size < n:
                self.size <<= 1
            self.minv = [0] * (2 * self.size)
            self.maxv = [0] * (2 * self.size)
            self.lazy = [0] * (2 * self.size)
            for i in range(n):
                self.minv[self.size + i] = i + 1
                self.maxv[self.size + i] = i + 1
            for i in range(self.size - 1, 0, -1):
                self.pull(i)

        def pull(self, i):
            self.minv[i] = min(self.minv[2*i], self.minv[2*i+1])
            self.maxv[i] = max(self.maxv[2*i], self.maxv[2*i+1])

        def apply(self, i, value):
            self.minv[i] += value
            self.maxv[i] += value
            self.lazy[i] += value

        def push(self, i):
            if self.lazy[i] != 0:
                self.apply(2*i, self.lazy[i])
                self.apply(2*i+1, self.lazy[i])
                self.lazy[i] = 0

        def range_add(self, l, r, value):
            l += self.size
            r += self.size + 1
            l0, r0 = l, r
            while l < r:
                if l & 1:
                    self.apply(l, value)
                    l += 1
                if r & 1:
                    r -= 1
                    self.apply(r, value)
                l >>= 1
                r >>= 1
            for i in [l0, r0-1]:
                i >>= 1
                while i:
                    self.pull(i)
                    i >>= 1

        def find_first_ge(self, x):
            if self.maxv[1] < x:
                return -1
            node = 1
            l = 0
            r = self.size
            while node < self.size:
                self.push(node)
                mid = (l + r) // 2
                if self.maxv[2*node] >= x:
                    node = 2*node
                    r = mid
                else:
                    node = 2*node + 1
                    l = mid
            if l >= self.n:
                return -1
            return l

        def find_last_le(self, x):
            if self.minv[1] > x:
                return -1
            node = 1
            l = 0
            r = self.size
            while node < self.size:
                self.push(node)
                mid = (l + r) // 2
                if self.minv[2*node+1] <= x:
                    node = 2*node + 1
                    l = mid
                else:
                    node = 2*node
                    r = mid
            if l >= self.n:
                return -1
            return l

        def get_all(self):
            res = [0] * self.n
            def dfs(node, l, r):
                if node >= self.size:
                    if l < self.n:
                        res[l] = self.minv[node]
                    return
                self.push(node)
                mid = (l + r) // 2
                dfs(2*node, l, mid)
                dfs(2*node+1, mid, r)
            dfs(1, 0, self.size)
            return res

    st = SegmentTree(MAX)
    for L, R in intervals:
        l = st.find_first_ge(L)
        if l == -1:
            continue
        r = st.find_last_le(R)
        if r == -1 or l > r:
            continue
        st.range_add(l, r, 1)

    final = st.get_all()
    out = []
    for X in queries:
        out.append(str(final[X-1]))
    sys.stdout.write("\n".join(out))

