import sys

def mat_mul(A, B, mod):
    N = len(A)
    C = [[0] * N for _ in range(N)]
    for i in range(N):
        Ai = A[i]
        Ci = C[i]
        for k in range(N):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                for j in range(N):
                    Ci[j] = (Ci[j] + aik * Bk[j]) % mod
    return C

def mat_pow(A, exp, mod):
    N = len(A)
    # identity matrix
    result = [[0] * N for _ in range(N)]
    for i in range(N):
        result[i][i] = 1
    base = A
    while exp > 0:
        if exp & 1:
            result = mat_mul(result, base, mod)
        base = mat_mul(base, base, mod)
        exp >>= 1
    return result

def solve():
    import sys
    input = sys.stdin.readline
    N, p = map(int, input().split())
    A = [list(map(int, input().split())) for _ in range(N)]

    if p == 2:
        # Construct B: zeros become 1
        B = [[1 if A[i][j] == 0 else A[i][j] for j in range(N)] for i in range(N)]
        S = mat_mul(B, B, 2)
        for row in S:
            print(' '.join(map(str, row)))
        return

    # Count zeros
    K = sum(1 for i in range(N) for j in range(N) if A[i][j] == 0)
    factor = pow(p - 1, K, p)

    # Compute A^p
    A_p = mat_pow(A, p, p)

    # Diagonal zeros
    diag_zero = [A[i][i] == 0 for i in range(N)]

    # Compute base_extra = M_row + M_col (+ M_mid if p==3)
    base_extra = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            val = 0
            if diag_zero[i]:
                val += A[i][j]
            if diag_zero[j]:
                val += A[i][j]
            if p == 3 and A[i][j] == 0 and A[j][i] != 0:
                val += A[j][i]
            base_extra[i][j] = val % p

    if p == 3:
        sign = 1 if K % 2 == 0 else (p - 1)
        extra = [[(sign * base_extra[i][j]) % p for j in range(N)] for i in range(N)]
        S = [[(factor * A_p[i][j] + extra[i][j]) % p for j in range(N)] for i in range(N)]
    else:
        # p > 3
        temp = [[(A_p[i][j] + base_extra[i][j]) % p for j in range(N)] for i in range(N)]
        S = [[(factor * temp[i][j]) % p for j in range(N)] for i in range(N)]

    for row in S:
        print(' '.join(map(str, row)))

