            for u in cycle_nodes:
                rep[u] = r

    # Build children list for the forest
    children = [[] for _ in range(N+1)]
    for i in range(1, N+1):
        if not in_cycle[i]:
            p = A[i]
            root_p = rep[p]
            children[root_p].append(i)

    # DP computation
    dp = [None]*(N+1)
    def dfs(v):
        if not children[v]:
            dp[v] = [0] + [1]*M
            return
        for c in children[v]:
            dfs(c)
        dp_v = [0] + [1]*M
        for c in children[v]:
            ps = [0]*(M+1)
            s = 0
            for k in range(1, M+1):
                s = (s + dp[c][k]) % MOD
                ps[k] = s
            for k in range(1, M+1):
                dp_v[k] = dp_v[k] * ps[k] % MOD
        dp[v] = dp_v

    ans = 1
    for i in range(1, N+1):
        if in_cycle[i] and rep[i] == i:
            dfs(i)
            total = sum(dp[i][1:]) % MOD
            ans = ans * total % MOD
    print(ans)

