class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter

        n = len(s)
        freq = [0] * 26
        for c in s:
            freq[ord(c) - ord('a')] += 1

        # Strategy: try all possible target counts k (1 to n) and compute min cost
        ans = float('inf')
        max_k = n

        for k in range(1, max_k + 1):
            cost = 0
            valid = True
            for f in freq:
                if f == 0:
                    # Need to insert k occurrences of this character
                    cost += k
                else:
                    # We need to change count f to become 0 or k
                    if f >= k:
                        cost += f - k  # delete f-k characters
                    else:
                        cost += k - f  # insert k-f characters (or change)
                if cost >= ans:
                    valid = False
                    break
            if valid:
                ans = min(ans, cost)

        return ans

