class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        size = [1] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if size[rx] < size[ry]:
                rx, ry = ry, rx
            parent[ry] = rx
            size[rx] += size[ry]

        # Filter out elements > threshold - they form isolated nodes
        # Group by value for efficient lookup
        val_to_indices = {}
        for i, v in enumerate(nums):
            if v <= threshold:
                val_to_indices.setdefault(v, []).append(i)

        # For each divisor d from 1 to threshold, find all values in nums that are multiples of d
        # If two values are both multiples of d and d <= threshold, then lcm(a,b) could be <= threshold
        # Actually: lcm(a,b) <= threshold iff there exists a common multiple c <= threshold
        # So we can connect all numbers that share a common multiple <= threshold

        # Group indices by their common multiples
        # For each multiple m from 1 to threshold, find all nums[i] where m % nums[i] == 0
        # All such numbers are pairwise connected (they all divide m, so lcm <= m <= threshold)

        multiples = {}
        for i, v in enumerate(nums):
            if v > threshold:
                continue
            # Find all multiples of v up to threshold
            for m in range(v, threshold + 1, v):
                if m not in multiples:
                    multiples[m] = i
                else:
                    # Union this index with the first index in this multiple group
                    union(multiples[m], i)

        # Count distinct connected components
        components = set()
        for i in range(n):
            if nums[i] > threshold:
                # These are isolated components
                components.add(('iso', i))
            else:
                components.add(find(i))

        return len(components)
